import os, re
from collections import Counter, deque

# Load grids
d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

# Parse demo pairs
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

test_input = G['Test input']
print("Test input size:", len(test_input) if test_input else 'empty', "x", len(test_input[0]) if test_input else 0)

# Find components by color
def find_all_cells_by_color(grid):
    cells_by_color = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color == 0:
                continue
            if color not in cells_by_color:
                cells_by_color[color] = []
            cells_by_color[color].append((r, c))
    return cells_by_color

# Check if cells are connected (4-way)
def are_connected(cells):
    if len(cells) <= 1:
        return True
    visited = set()
    q = deque()
    start = cells[0]
    visited.add(start)
    q.append(start)
    while q:
        r, c = q.popleft()
        for nr, nc in [(r+1,c), (r-1,c), (r,c+1), (r,c-1)]:
            if (nr, nc) in cells and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(cells)

cells_by_color = find_all_cells_by_color(test_input)
print("\nTest input components:")
for color, cells in sorted(cells_by_color.items()):
    print(f"Color {color}: {len(cells)} cells, connected={are_connected(cells)}")
